mapper.select:
select p.user_id userId, p.lat, p.lng, p.real_lat realLat, p.real_lng realLng, p.locate_type locateType,
p.uptime, p.city, p.province, p.version from corgi_user_position p

    join corgi_user_follow f on f.user_id = p.user_id
    and f.follow_user_id = #{userId}
    and f.is_deleted = '0'

where p.city = #{city}
limit #{start}, #{size}

select p.user_id from corgi_user_position p
left join corgi_user_detail d on p.user_id = d.user_id

    join corgi_user_follow f1 on f1.user_id = #{range.userId} and f1.follow_user_id = p.user_id and
    f1.is_deleted = '0'


    join corgi_user_follow f2 on f2.follow_user_id = #{range.userId} and f2.user_id = p.user_id and
    f2.is_deleted = '0'

where p.lat >= #{range.beginLat} and p.lat <= #{range.endLat}
and p.lng >= #{range.beginLng} and p.lng <= #{range.endLng}

    and d.height >= #{range.startHeight}


    and d.height <= #{range.endHeight}


    and d.weight >= #{range.startWeight}


    and d.weight <= #{range.endWeight}


    and d.relation in ${range.relation}


    and d.role in ${range.role} and d.hide_role != '1'


    and d.group in ${range.group} and d.hide_group != '1'


    order by st_distance_sphere(point(#{range.lng},#{range.lat}),p.pt)



    limit #{range.limit}

select distinct p.user_id from corgi_user_position p
where p.lat < 90 and p.lng < 180

    and p.city = #{range.city}

order by st_distance_sphere(point(#{range.lng},#{range.lat}),p.pt)

    limit #{range.limit}

select
d.user_id userId,
d.nickname nickname,
d.check_nickname checkNickname,
d.avatar avatar,
d.avatar_status avatarStatus,
d.avatar_check_status avatarCheckStatus,
d.role role,
d.hide_role hideRole,
d.group `group`,
d.hide_group `hideGroup`,
d.hide_prefer_group `hidePreferGroup`,
d.con con,
d.relation,
d.desc,
d.check_desc checkDesc,
p.lat lat,
p.lng lng,
if(p.fuptime > 0, p.fuptime, p.uptime) `time`,
d.cime createTime,
d.check_status checkStatus
from corgi_user_detail d
left join corgi_user_position p on p.user_id = d.user_id
left join corgi_user_login l on l.id = d.user_id
where 1=1

    and UPPER(`nickName`) like UPPER(concat('%',#{userDetail.nickname},'%'))


    and l.tel_no = #{userDetail.telNo}


    and `height` = #{userDetail.height}


    and `weight` = #{userDetail.weight}


    and `desc` like concat('%',#{userDetail.desc},'%')


    and `role` = #{userDetail.role}


    and `character` = #{userDetail.character}


    and `group` = #{userDetail.group}


    and `birthday` = #{userDetail.birthday}


    and `city` = #{userDetail.city}


    and `con` = #{userDetail.con}


    and `relation` = #{userDetail.relation}


    and d.user_id = #{userDetail.userId}


    and d.check_status = #{userDetail.checkStatus}


    and d.avatar_status = #{userDetail.avatarStatus}


    and (d.avatar_status = 'influencer' or (d.vip_status = '1' and d.vip_expire < date_format(NOW(),'%Y-%m-%d
    %H:%i:%s')))


    and exists (select 1 from corgi_user_goods g where g.user_id = d.user_id)


order by d.user_id
limit #{start},#{size}

select d.user_id userId, d.nickname nickname, d.avatar avatar, d.character `character`, d.avatar_check_status avatarCheckStatus, b.city from corgi_influencer_billboard b left join corgi_user_detail d on b.user_id = d.user_id left join corgi_user_login l on l.id = d.user_id where b.user_id != '8'
and d.nickname like concat('%',#{query.nickname},'%')
and l.tel_no = #{query.telNo}
and d.character = #{query.character}
order by b.fan desc limit #{start}, #{size}

select
count(1)
from corgi_user_detail d
where 1=1

    and UPPER(`nickName`) like UPPER(concat('%',#{userDetail.nickname},'%'))


    and `height` = #{userDetail.height}


    and `weight` = #{userDetail.weight}


    and `desc` like concat('%',#{userDetail.desc},'%')


    and `role` = #{userDetail.role}


    and `relation` = #{userDetail.relation}


    and `character` = #{userDetail.character}


    and `group` = #{userDetail.group}


    and `birthday` = #{userDetail.birthday}


    and `city` = #{userDetail.city}


    and `con` = #{userDetail.con}


    and d.user_id = #{userDetail.userId}


    and d.check_status = #{userDetail.checkStatus}

select count(1)
from corgi_user_position p
         left join corgi_user_login l on l.id = p.user_id
where p.uptime >= #{beginTime}
  and p.uptime <= #{endTime}
  and l.tel_no not like '3%'

select if(vip_status = 1, vip_expire, '-')
from corgi_user_detail
where user_id = #{userId}
